 static void Text(System.Text.StringBuilder page,double scale,double x,double y,string value){page.AppendFormat(System.Globalization.CultureInfo.InvariantCulture,"BT /F1 {0:0.###} Tf 1 0 0 1 {1:0.###} {2:0.###} Tm ({3}) Tj ET\n",7*scale,x*scale,(842-y)*scale,Esc(value));}
